from fractions import Fraction

def rn_derivative(p, q):
    """p and q map each outcome to a Fraction. Return Z = dQ/dP as a dict.
    Raise ValueError if some outcome has q > 0 and p = 0."""
    z = {}
    for w in p:
        if p[w] == 0:
            if q[w] > 0:
                raise ValueError("Q gives chance to an outcome P rules out")
            z[w] = Fraction(0)
        else:
            z[w] = Fraction(q[w]) / Fraction(p[w])
    return z

def expect_q(p, z, X):
    """E_Q[X] = E_P[Z X], exactly. X is a function of the outcome."""
    return sum((Fraction(p[w]) * z[w] * X(w) for w in p), Fraction(0))

def prob_q(p, z, A):
    """Q(A) = E_P[Z 1_A], exactly. A is a set of outcomes."""
    return expect_q(p, z, lambda w: 1 if w in A else 0)

